package main

import (
	"context"
	"github.com/threadify/sdk-go"
)

func main() {
	ctx := context.Background()
	conn, _ := threadify.Connect(ctx, "YOUR_API_KEY",
		threadify.WithServiceName("my-service"),
	)
	defer conn.Close()

	// Start a thread with a descriptive label
	thread, _ := conn.Start(ctx, "Order-Processing-ORD-12345", "")

	// Record a step
	thread.Step("payment_processed").
		AddContext(map[string]interface{}{
			"amount":   99.99,
			"currency": "USD",
		}).
		Success(ctx)
}

