import { Threadify } from '@threadify/sdk';

const connection = await Threadify.connect('YOUR_API_KEY', 'my-service');

// Start with latest version of contract and a label
const thread = await connection.start('Order-Fulfillment-ORD-123', 'order_fulfillment', { serviceName: 'merchant' });

// Contract validates: entry point, required fields, role access
await thread.step('order_placed')
  .addContext({ 
    order_id: 'ORD-123',
    product_id: 'PROD-456',
    quantity: '2'
  })
  .success();

// Contract ensures this is a valid next step
await thread.step('payment_processed')
  .addContext({ 
    payment_id: 'PAY-789',
    amount: '99.99'
  })
  .success();

