from threadify import ThreadifyClient

client = ThreadifyClient(
    api_key='YOUR_API_KEY',
    base_url='http://localhost:3000'
)

# Start a thread with a contract
thread = client.start_thread(
    name='order_processing',
    contract_name='ecommerce_order',
    contract_version='v1',
    metadata={'order_id': '12345'}
)

# Record steps - Threadify validates against contract
thread.record_step(
    name='order_placed',
    status='success',
    context={'items': 3, 'total': 299.97}
)

thread.record_step(
    name='payment_processed',
    status='success',
    context={'payment_id': 'pay_123'}
)

