import { Threadify } from '@threadify/sdk';

const connection = await Threadify.connect('YOUR_API_KEY', 'my-service');

// Subscribe to violations
connection.onViolation('payment_processed', (notification) => {
  console.log('Payment violation:', notification.message);
  // Implement circuit breaker, retry logic, etc.
  notification.ack(); // IMPORTANT: Must ACK
});

// Subscribe to completions
connection.onCompleted('order_delivered', (notification) => {
  console.log('Order completed:', notification.message);
  // Send confirmation email, update analytics, etc.
  notification.ack();
});

// Subscribe to failures
connection.onFailed('payment_processed', (notification) => {
  console.log('Payment failed:', notification.message);
  notification.ack();
});

with_reactions.go:
package main

import "github.com/threadify/sdk-go"

func main() {
	client := threadify.NewClient(
		threadify.WithAPIKey("YOUR_API_KEY"),
		threadify.WithBaseURL("http://localhost:3000"),
	)

	// Subscribe to violations
	client.OnViolation("payment_processed", func(n *threadify.Notification) {
		log.Printf("Payment violation: %+v", n)
		// Implement circuit breaker, retry logic, etc.
		n.Ack()
	})

	// Subscribe to completions
	client.OnCompleted("order_delivered", func(n *threadify.Notification) {
		log.Printf("Order completed: %+v", n)
		// Send confirmation email, update analytics, etc.
		n.Ack()
	})

	// Start listening for notifications
	client.Connect()
}
